window.CP_ITEMS=window.CP_ITEMS||{};window.CP_ITEMS["动物"]=[{"uid":"f6b75eb2-255e-4071-bf01-a5db4d409051","title":"孤雁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["孤雁不饮啄，飞鸣声念群。","谁怜一片影，相失万重云。","望尽似犹见，哀多如更闻。","野鵶无意绪，鸣噪自纷纷。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.526},{"uid":"d4c03bc1-0596-4177-88ba-e42a97b0a7d9","title":"鼓吹曲辞 君马黄","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["君马黄，我马白。","马色虽不同，人心本无隔。","共作游冶盘，双行洛阳陌。","长劒既照曜，高冠何赩赫。","各有千金裘，俱为五侯客。","猛虎落陷穽，壮夫时屈厄。","相知在急难，独好亦何益。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"慷慨","mood2":["孤寂"],"scene":[],"cats":{"抒情":["孤独"],"动物":["写马"]},"theme_conf":0.65},{"uid":"f8e07cab-06f6-4ea0-a6b6-815bd8c22506","title":"归燕","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["不独避霜雪，其如俦侣稀。","四时无失序，八月自知归。","春色岂相访，众雏还识机。","故巢傥未毁，会傍主人飞。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","雪","春","月"],"cats":{"抒情":["思乡","孤独"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.519},{"uid":"c353940d-4bbc-4420-83bf-07cb4606d35f","title":"赋得早雁出云鸣","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["初秋玉露清，早雁出空鸣。","隔云时乱影，因风乍含声。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"四季":["秋天"],"天气":["写云"],"动物":["写鸟"]},"theme_conf":0.697},{"uid":"6a35a5c8-851b-4f2d-aa73-a0fd3b2fd2b6","title":"郑驸马宅宴洞中","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["主家阴洞细烟雾，留客夏簟清琅玕。","春酒杯浓琥珀薄，冰浆椀碧玛瑙寒。","误疑茅堂过江麓，已入风磴霾云端。","自是秦楼压郑谷，时闻杂佩声珊珊。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","夏","春"],"cats":{"抒情":["思乡"],"四季":["春天","夏天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"cp9a38d953d1f347","title":"瑞鹤仙","author":"陆叡","dynasty":"宋","section":"宋词","form":"词","paragraphs":["湿云黏雁影。","望征路愁迷，离绪难整。","千金买光景。","但疏钟催晓，乱鸦啼暝。","花暗省。","许多情、相逢梦境。","便行云、都不归来，也合寄将音信。","孤迥。","盟鸾心在，跨鹤程高，后期无准。","情丝待翦。","翻惹得，旧时恨。","怕天教何处，参差双燕，还染残朱剩粉。","对菱花、与说相思，看谁瘦损。"],"theme":"送别","theme2":["爱情相思","游仙梦幻"],"style":"沉郁","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["爱情","思念","伤感"],"动物":["写鸟"]},"theme_conf":0.437},{"uid":"38c223e9-27da-4342-a0aa-13e57cbb758f","title":"又判争猫儿状","author":"裴谞","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["猫儿不识主，傍家搦老鼠。","两家不须争，将来与裴谞。"],"theme":"讽喻刺世","theme2":[],"style":"沉郁","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"动物":["写猫"]},"theme_conf":0.6},{"uid":"06bd32a2-f9f5-4bfe-a55e-fadd67afc789","title":"相和歌辞 饮马长城窟行","author":"王建","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长城窟，长城窟边多马骨。","古来此地无井泉，赖得秦家筑城卒。","征人饮马愁不回，长城变作望乡堆。","蹄迹未干人去近，续后马来泥污尽。","枕弓睡著待水生，不见阴山在前阵。","马蹄足脱装马头，健儿战死谁封侯。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":["相思","悲怆"],"scene":[],"cats":{"抒情":["思念","思乡","伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.631},{"uid":"9a2c1932-4219-483b-a14b-52dc7265f6fb","title":"同李太守登历下古城员外新亭亭对鹊湖","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["新亭结搆罢，隐见清湖阴。","迹籍台观旧，气溟海岳深。","圆荷想自昔，遗堞感至今。","芳宴此时具，哀丝千古心。","主称寿尊客，筵秩宴北林。","不阻蓬荜兴，得兼梁甫吟。"],"theme":"山水田园","theme2":["咏史怀古","悼亡挽歌"],"style":"清新","style2":[],"mood":"欢愉","mood2":["悲怆"],"scene":["楼","江"],"cats":{"抒情":["悼亡","怀古"],"动物":["写鸟"]},"theme_conf":0.353},{"uid":"890d8eee-81f6-40f8-8887-810b30665d5f","title":"横吹曲辞 紫骝马","author":"秦韬玉","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["渥洼奇骨本难求，况是豪家重紫骝。","臕大宜悬银压銙，力浑欺却玉衔头。","生狞弄影风随起，躞蹀冲尘汗满沟。","若遇丈夫皆调御，任从骑取觅封侯。"],"theme":"咏物","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"动物":["写马"]},"theme_conf":0.95},{"uid":"cp4d7a1643bbbda8","title":"喜迁莺","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["月波疑滴。","望玉壶天近，了无尘隔。","翠眼圈花，冰丝织练，黄道宝光相直。","自怜诗酒瘦，难应接、许多春色。","最无赖，是随香趁烛，曾伴狂客。","踪迹。","谩记忆。","老了杜郎，忍听东风笛。","柳院灯疏，梅厅雪在，谁与细倾春碧。","旧情拘未定，犹自学、当年游历。","怕万一，误玉人、夜寒帘隙。"],"theme":"羁旅思乡","theme2":[],"style":"婉约","style2":["豪放","绮丽"],"mood":"欢愉","mood2":["相思"],"scene":["春","冬"],"cats":{"抒情":["思念","思乡"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.65},{"uid":"451fc40e-4dad-47ec-88e7-bb54fbc6bb60","title":"东平留赠狄司马","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["古人无宿诺，兹道以为难。","万里赴知己，一言诚可叹。","马蹄经月窟，劒术指楼兰。","地出北庭尽，城临西海寒。","森然瞻武库，则是弄儒翰。","入幕绾银绶，乘轺兼铁冠。","练兵日精锐，杀敌无遗残。","献捷见天子，论功俘可汗。","激昂丹墀下，顾盼青云端。","谁谓纵横策，翻为权势干。","将军既坎𡒄，使者亦辛酸。","耿介挹三事，羇离从一官。","知君不得意，他日会鹏抟。"],"theme":"寄赠酬答","theme2":["边塞征战"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["友情"],"人生":["梦想"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.86},{"uid":"4b20b87c-18e6-4769-b07e-72665771fd11","title":"相和歌辞 饮马长城窟行","author":"袁朗","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动秋草，清跸长安道。","长城连不穷，所以隔华戎。","规模惟圣作，荷负晓成功。","鸟庭已向内，龙荒更凿空。","玉关尘卷静，金微路已通。","汤征随北怨，舜咏起南风。","画野功初立，绥边事云集。","朝服践狼居，凯歌旋马邑。","山响传凤吹，霜华藻琼钑。","属国拥节归，单于款关入。","日落寒云起，惊沙被原隰。","零落叶已寒，河流清且急。","四时徭役尽，千载干戈戢。","太平今若斯，汗马竟无施。","惟当事笔研，归去草封禅。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["冲淡","绮丽"],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["秋"],"cats":{"四季":["秋天"],"天气":["写风"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.522},{"uid":"884a25ac-d492-45dc-aeb8-d1e7c987ff0a","title":"燕居","author":"羊士谔","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["秋斋膏沐暇，旭日照轩墀。","露重芭蕉叶，香凝橘柚枝。","简书随吏散，宝骑与僧期。","报国得何力，流年已觉衰。"],"theme":"咏怀抒感","theme2":[],"style":"清新","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["爱国"],"四季":["秋天"],"天气":["太阳"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"03f25790-0eb4-41e1-861e-fcf5e124ea89","title":"怀江上（句）（卢延逊五举方登第。〖2〗尝作诗云。「狐冲」二句，租庸张相濬每诵之。又「饿猫」二句，成中令汭激赏之。又「栗爆」二句，王中懿建爱之。卢尝谓人曰：「平生投谒公卿，不意得猫儿狗子之力也。」） 一","author":"卢延让","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["狐冲官道过，犬刺客门开（一作「狗判店门开」）。","〖3〗。"],"theme":"民生疾苦","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"抒情":["怀古"],"动物":["写猫"]},"theme_conf":0.546},{"uid":"c680a907-39d1-4968-b638-3bdb6c97eb9b","title":"相和歌辞 燕歌行","author":"陶翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["请君留楚调，听我吟燕歌。","家在辽水头，边风意气多。","出身为汉将，正值戎未和。","雪中凌天山，冰上渡交河。","大小百余战，封侯竟蹉跎。","归来霸陵下，故旧无相过。","雄劒委尘匣，空门唯雀罗。","玉𥮾还赵女，宝瑟付齐娥。"],"theme":"边塞征战","theme2":["羁旅思乡","哲理悟道"],"style":"清新","style2":["绮丽"],"mood":"慷慨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡"],"人生":["战争"],"动物":["写鸟"]},"theme_conf":0.403},{"uid":"de948fac-a55e-462b-98f8-aa3b9214fc54","title":"醉为马坠诸公携酒相看","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["甫也诸侯老宾客，罢酒酣歌拓金戟。","骑马忽忆少年时，散蹄迸落瞿塘石。","白帝城门水云外，低身直下八千尺。","粉堞电转紫游缰，东得平冈出天壁。","江村野堂争入眼，垂鞭亸鞚凌紫陌。","向来皓首惊万人，自倚红颜能骑射。","安知决臆追风足，朱汗骖驔犹喷玉。","不虞一蹶终损伤，人生快意多所辱。","职当忧戚伏衾枕，况乃迟暮加烦促。","明知来问腆我颜，杖藜强起依僮仆。","语尽还成开口笑，提携别埽清谿曲。","酒肉如山又一时，初筵哀丝动豪竹。","共指西日不相贷，喧呼且复杯中渌。","何必走马来为问，君不见嵇康养生遭杀戮。"],"theme":"寄赠酬答","theme2":["山水田园"],"style":"豪放","style2":["沉郁"],"mood":"欢愉","mood2":["相思","悲怆"],"scene":["酒"],"cats":{"抒情":["思念","伤感"],"动物":["写马"],"食物":["写酒"]},"theme_conf":0.82},{"uid":"cp2e2a1c2fd58b4f","title":"喜迁莺","author":"刘一止","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晓光催角。","听宿鸟未惊，邻鸡先觉。","迤逦烟村，马嘶人起，残月尚穿林薄。","泪痕带霜微凝，酒力冲寒犹弱。","叹倦客、悄不禁，重染风尘京洛。","追念，人别后，心事万重，难觅孤鸿托。","翠幌娇深，曲屏香暖，争念岁寒飘泊。","怨月恨花烦恼，不是不曾经著。","这情味，望一成消减，新来还恶。"],"theme":"山水田园","theme2":["送别"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":["欢愉"],"scene":["鸟","春"],"cats":{"抒情":["伤感"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.5},{"uid":"601d90fb-3589-44f1-9a25-9e16af2102c3","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["把烛成桥夜，回舟坐客时。","天高云去尽，江迥月来迟。","衰谢多扶病，招邀屡有期。","异方乘此兴，乐罢不无悲。"],"theme":"山水田园","theme2":[],"style":"悲慨","style2":["幽峭","沉郁"],"mood":"欢愉","mood2":["悲怆"],"scene":["江","冬"],"cats":{"抒情":["伤感"],"四季":["冬天"],"山水":["江河"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":1.0},{"uid":"565d931a-ff49-4f37-b633-524b48c2f4f0","title":"寻陆鸿渐不遇","author":"皎然","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["移家虽带郭，野径入桑麻。","近种篱边菊，秋来未著花。","扣门无犬吠，欲去问西家。","报道山中去，归时每日斜。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["秋","山"],"cats":{"四季":["秋天"],"生活":["乡村","田野"],"动物":["写鸟"]},"theme_conf":0.439},{"uid":"18a2193c-1bd7-4426-b17f-d02a8a4aec1b","title":"莺莺歌","author":"李绅","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伯劳飞迟燕飞疾，垂杨绽金花笑日。","绿窗娇女字莺莺，金雀娅鬟年十七。","黄姑上天阿母在，寂莫霜姿素莲质。","门掩重关萧寺中，芳草花时不曾出。"],"theme":"哲理悟道","theme2":[],"style":"清新","style2":["冲淡"],"mood":"孤寂","mood2":["欢愉"],"scene":["鸟","春"],"cats":{"四季":["春天"],"人物":["母亲"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"c611bf84-57f9-44ee-ac22-d7a270a21190","title":"送马将军奏事毕归滑州使幕","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["吴门别后蹈沧州，帝里相逢俱白头。","自叹马卿常带病，还嗟李广未封侯。","棠梨宫里瞻龙衮，细柳营前著豹裘。","想到滑台桑叶落，黄河东注荻花秋。"],"theme":"边塞征战","theme2":["送别"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["江","秋","江南"],"cats":{"四季":["秋天"],"山水":["黄河"],"动物":["写马"]},"theme_conf":0.574},{"uid":"cp60a401fbbbc431","title":"莺啼序","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["残寒正欺病酒，掩沈香绣户。","燕来晚、飞入西城，似说春事迟暮。","画船载、清明过却，晴烟冉冉吴宫树。","念羁情游荡，随风化为轻絮。","十载西湖，傍柳系马，趁娇尘软雾。","溯红渐、招入仙溪，锦儿偷寄幽素。","倚银屏、春宽梦窄，断红湿、歌纨金缕。","暝堤空，轻把斜阳，总还鸥鹭。","幽兰旋老，杜若还生，水乡尚寄旅。","别后访、六桥无信，事往花委，瘗玉埋香，几番风雨。","长波妒盼，遥山羞黛，渔灯分影春江宿，记当时、短楫桃根渡。","青楼彷佛，临分败壁题诗，泪墨惨澹尘土。","危亭望极，草色天涯，吹鬓侵半苎。","暗点检、离痕欢唾，尚染鲛绡，凤迷归，破鸾慵舞。","殷勤待写，书中长恨，蓝霞辽海沈过雁，漫相思、弹入哀筝柱。","伤心千里江南，怨曲重招，断魂在否。"],"theme":"悼亡挽歌","theme2":["送别"],"style":"沉郁","style2":["绮丽","婉约"],"mood":"相思","mood2":["愁怨"],"scene":["江南","鸟","春"],"cats":{"抒情":["离别","思念","伤感","悼亡"],"四季":["春天"],"山水":["西湖"],"生活":["写桥"],"节日":["清明节"],"动物":["写鸟"]},"theme_conf":0.93},{"uid":"dd4808c5-cefb-4840-8782-a1636acc9856","title":"琴曲歌辞 走马引","author":"李贺","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["我有辞乡劒，玉锋堪截云。","襄阳走马客，意气自生春。","朝嫌劒光静，暮嫌劒花冷。","能持劒向人，不解持照身。"],"theme":"羁旅思乡","theme2":["闲适隐逸"],"style":"沉郁","style2":[],"mood":"慷慨","mood2":["恬淡"],"scene":["春"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.612},{"uid":"a06cb556-2b4d-4b1c-a52a-fcff10b7f87e","title":"杂曲歌辞 昔昔盐 空梁落燕泥","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["春至今朝燕，花时伴独嗁。","飞斜珠箔隔，语近画梁低。","帷卷闲窥户，床空暗落泥。","谁能长对此，双去复双栖。"],"theme":"闺情宫怨","theme2":[],"style":"冲淡","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","闺怨"],"动物":["写鸟"]},"theme_conf":0.92},{"uid":"eeafa160-a9d9-484d-9cbe-01a796260aa2","title":"相和歌辞 门有车马客行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["财雄重交结，戚里擅豪华。","曲台临上路，高门抵狭斜。","赭汗千金马，绣毂五香车。","白鹤随飞盖，朱鹭入鸣笳。","夏莲开劒水，春桃发露花。","轻裙染回雪，浮蚁泛流霞。","高谈辨飞兔，摛藻握灵蛇。","逢恩借羽翼，失路委泥沙。","暧暧风烟晚，路长归骑远。","日斜青琐第，尘飞金谷苑。","危弦促柱奏巴渝，遗簪堕珥解罗襦。","如何守直道，飜使谷名愚。"],"theme":"羁旅思乡","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"相思","mood2":[],"scene":["夏","花","雪","春"],"cats":{"抒情":["思乡"],"四季":["春天","夏天"],"动物":["写马"]},"theme_conf":0.661},{"uid":"05d03b46-d786-4acf-995e-a20721f16583","title":"秋莺","author":"后主煜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["残莺何事不知秋，横过幽林尚独游。","老舌百般倾耳听，深黄一点入烟流。","栖迟背世同悲鲁，浏亮如笙碎在缑。","莫更留连好归去，露华凄冷蓼花愁。"],"theme":"咏物","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["悲怆"],"scene":["秋","春","鸟"],"cats":{"抒情":["伤感"],"四季":["春天","秋天"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"4b0047aa-a695-43a5-a4a7-b1f2529ba792","title":"聪马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["邓公马癖人共知，初得花骢大宛种。","夙昔传闻思一见，牵来左右神皆竦。","雄姿逸态何崷崪，顾影骄嘶自矜宠。","隅目青荧夹镜悬，肉骏碨礌连钱动。","朝来久试华轩下，未觉千金满高价。","赤汗微生白雪毛，银鞍却覆香罗帕。","卿家旧赐公取之，天厩真龙此其亚。","昼洗须腾泾渭深，朝趋可刷幽幷夜。","吾闻良骥老始成，此马数年人更惊。","岂有四蹄疾于鸟，不与八骏俱先鸣。","时俗造次那得致，云雾晦冥方降精。","近闻下诏喧都邑，肯使骐𬴊地上行。"],"theme":"咏物","theme2":["羁旅思乡"],"style":"绮丽","style2":["婉约"],"mood":"恬淡","mood2":[],"scene":["夜","花","雪"],"cats":{"抒情":["思乡"],"动物":["写马"]},"theme_conf":0.97},{"uid":"cp6fe48a6dc4fefb","title":"瑞鹤仙","author":"袁去华","dynasty":"宋","section":"宋词","form":"词","paragraphs":["郊原初过雨。","见败叶零乱，风定犹舞。","斜阳挂深树。","映浓愁浅黛，遥山眉妩。","来时旧路。","尚岩花、娇黄半吐。","到而今，唯有溪边流水，见人如故。","无语。","邮亭深静，下马还寻，旧曾题处。","无聊倦旅。","伤离恨，最愁苦。","纵收香藏镜，他年重到，人面桃花在否。","念沈沈、小阁幽窗，有时梦去。"],"theme":"爱情相思","theme2":["羁旅思乡","游仙梦幻","闺情宫怨"],"style":"沉郁","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["山","楼","鸟","花","雨"],"cats":{"抒情":["思乡","伤感","闺怨"],"动物":["写鸟"]},"theme_conf":0.79},{"uid":"402c5cc0-8255-4a01-8e5e-2641417bf8a2","title":"杂曲歌辞 白马篇","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["龙马花雪毛，金鞍五陵豪。","秋霜切玉劒，落日明珠袍。","鬬鸡事万乘，轩盖一何高。","弓摧宜山虎，手接泰山猱。","酒后竞风彩，三杯弄宝刀。","杀人如翦草，剧孟同游遨。","发愤去函谷，从军向临洮。","叱咤万战场，匈奴尽波涛。","归来使酒气，未肯拜萧曹。","羞入原宪室，荒径隐蓬蒿。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["悲慨"],"mood":"慷慨","mood2":[],"scene":["山","酒","秋"],"cats":{"四季":["秋天"],"山水":["泰山"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.79},{"uid":"b7c8a7fe-7ad4-44fe-9b71-3c085eb5e999","title":"咏马鞭","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["龙竹养根凡几年，工人截之为长鞭。","一节一目皆天然，珠重重，星连连。","绕指柔，纯金坚，绳不直，规不圆。","把向空中捎一声，良马有心日驰千。"],"theme":"咏物","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"动物":["写马"]},"theme_conf":1.0},{"uid":"91233d92-0156-4ead-9981-a5b834f9a3d2","title":"杜鹃行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见昔日蜀天子，化作杜鹃似老乌。","寄巢生子不自啄，群鸟至今与哺雏。","虽同君臣有旧礼，骨肉满眼身羁孤。","业工窜伏深树里，四月五月偏号呼。","其声哀痛口流血，所诉何事常区区。","尔岂摧残始发愤，羞带羽翮伤形愚。","苍天变化谁料得，万事反复何所无。","万事反复何所无，岂忆当殿群臣趋。"],"theme":"咏物","theme2":["送别","亲情","山水田园"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":["相思","惆怅"],"scene":["鸟"],"cats":{"抒情":["思念","伤感"],"动物":["写鸟"]},"theme_conf":0.9},{"uid":"39c8eb21-2fd1-42bb-9540-3ff56ea983c3","title":"鼓吹曲辞 朱鹭","author":"张籍","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["翩翩兮朱鹭，来泛春塘栖绿树。","羽毛如翦色如染，远飞欲下双翅敛。","避人引子入深壍，动处水纹开滟滟。","谁知豪家网尔躯，不如饮啄江海隅。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"相思","mood2":[],"scene":["春","江"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.65},{"uid":"4b563103-d593-41f9-96a4-b65155ccbde4","title":"同鲜于洛阳于毕员外宅观画马歌","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["知君爱鸣琴，仍好千里马。","永日恒思单父中，有时心到宛城下。","遇客丹青天下才，白生胡雏控龙媒。","主人娱宾画障开，只言骐骥西极来。","半壁𫎺𧽼势不住，满堂风飘飒然度。","家僮愕视欲先鞭，枥马惊嘶还屡顾。","始知物妙皆可怜，燕昭市骏岂徒然。","纵令剪拂无所用，犹胜驽骀在眼前。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"动物":["写马"]},"theme_conf":0.682},{"uid":"2bdc3e83-80ca-4977-bbc1-cc1e37918e14","title":"送陆鸿渐山人采茶回","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["千峰待逋客，香茗复丛生。","采摘知深处，烟霞羡独行。","幽期山寺远，野饭石泉清。","寂寂燃灯夜，相思一磬声。"],"theme":"送别","theme2":["闲适隐逸","山水田园"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["山"],"cats":{"抒情":["思念","孤独"],"动物":["写鸟"],"食物":["写茶"]},"theme_conf":0.279},{"uid":"cf5eecaf-79f1-484c-93e2-8e28fb3c0816","title":"观八骏图","author":"刘叉","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["穆王八骏走不歇，海外去寻长日月。","五云望断阿母宫，归来落得新白发。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["月"],"cats":{"人物":["母亲"],"动物":["写马"]},"theme_conf":1.0},{"uid":"b39ad3db-8f27-43c9-a11d-9b16e5259431","title":"同马太守听九思法师讲金刚经","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["吾师晋阳宝，杰出山河最。","途经世谛间，心到空王外。","鸣钟山虎伏，说法天龙会。","了义同建瓴，梵法若吹籁。","深知亿劫苦，善喻恒沙大。","舍施割肌肤，攀缘去亲爱。","招提何清净，良牧驻轻盖。","露冕众香中，临人觉苑内。","心持佛印久，标割魔军退。","愿开初地因，永奉弥天对。"],"theme":"佛道禅颂","theme2":[],"style":"清新","style2":["绮丽","婉约"],"mood":"相思","mood2":[],"scene":["山"],"cats":{"动物":["写马"]},"theme_conf":0.94},{"uid":"b849afe9-f7db-4f53-b688-fafa65b264f1","title":"南海马大夫见惠著述三通勒成四帙上自邃古达于国朝采其菁华至简如富钦受嘉贶诗以谢之","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["红旗阅五兵，绛帐领诸生。","味道轻鼎食，退公犹笔耕。","青箱传学远，金匮纳书成。","一瞬见前事，九流当抗行。","编蒲曾苦思，垂竹媿无名。","今日承芳讯，谁言赠衮荣。"],"theme":"寄赠酬答","theme2":["送别","边塞征战"],"style":"豪放","style2":["旷达","绮丽"],"mood":"恬淡","mood2":[],"scene":["花"],"cats":{"抒情":["感恩"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.96},{"uid":"dfaaaf11-9ead-4921-a71e-1f60be94af03","title":"得柳员外书封寄近诗书中兼报新主行营兵马因代书戏答","author":"独孤及","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["郎官作掾心非好，儒服临戎政已闻。","说劒尝宗漆园吏，戒严应笑棘门军。","遥知抵掌论皇道，时复吟诗向白云。","百越待君言即叙，相思不敢怆离群。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":[],"mood":"相思","mood2":[],"scene":["园林","江南"],"cats":{"抒情":["思念"],"人生":["读书","战争"],"动物":["写马"],"植物":["柳树"]},"theme_conf":0.95},{"uid":"9f5ded08-4f6f-4641-878e-897904483479","title":"郡斋雨中与诸文士燕集","author":"韦应物","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["兵卫森画戟，宴寝凝清香。","海上风雨至，逍遥池阁凉。","烦疴近消散，嘉宾复满堂。","自慙居处崇，未覩斯民康。","理会是非遣，性达形迹忘。","鲜肥属时禁，蔬果幸见尝。","俯饮一杯酒，仰聆金玉章。","神欢体自轻，意欲凌风翔。","吴中盛文史，群彦今汪洋。","方知大藩地，岂曰财赋疆。"],"theme":"应制干谒","theme2":[],"style":"旷达","style2":["清新","绮丽"],"mood":"欢愉","mood2":[],"scene":["雨"],"cats":{"天气":["写雨"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"c9ef6401-b33c-4077-89bc-f01fc3279dce","title":"莺莺诗","author":"元稹","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["殷红浅碧旧衣裳，取次梳头暗澹妆。","夜合带烟笼晓日，牡丹经雨泣残阳。","低迷隐笑原非笑，散漫清香不似香。","频动横波嗔阿母，等闲教见小儿郎。"],"theme":"爱情相思","theme2":[],"style":"清新","style2":["冲淡"],"mood":"恬淡","mood2":["悲怆","欢愉"],"scene":["春","鸟","花","夜","雨"],"cats":{"四季":["春天"],"人物":["母亲","儿童"],"动物":["写鸟"]},"theme_conf":0.88},{"uid":"42bc232f-00c5-4e92-8c55-8f38280a9dbe","title":"杂曲歌辞 爱妾换马 一","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["一面妖桃千里蹏，娇姿骏背价应齐。","乍牵玉勒辞金栈，催整花钿出绣闺。","去日岂无沾袂泣，归时还有顿衔嘶。","婵娟躞蹀春风里，挥手摇鞭杨柳堤。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["中秋","春"],"cats":{"抒情":["闺怨"],"四季":["春天"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":1.0},{"uid":"8c811630-909b-4aa3-ac92-db90021e132d","title":"崔驸马山亭宴集","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["萧史幽栖地，林间蹋凤毛。","洑流何处入，乱石闭门高。","客醉挥金椀，诗成得绣袍。","清秋多宴会，终日困香醪。"],"theme":"山水田园","theme2":["闲适隐逸"],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["酒","山","楼","秋"],"cats":{"四季":["秋天"],"动物":["写马"]},"theme_conf":0.536},{"uid":"0a6798a1-eae0-48d8-9a2a-7dde2eae81fc","title":"琴曲歌辞 别鹤","author":"杨巨源","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["海鹤一为别，高程方杳然。","影摇江海路，思结潇湘天。","皎然仰白日，真姿栖紫烟。","含情九霄际，顾侣五云前。","遐心属清都，凄响激朱弦。","超摇间云雨，迢遰各山川。","东南信多水，会合当有年。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别"],"动物":["写鸟"]},"theme_conf":0.782},{"uid":"3a4f178b-0009-40ce-9c8d-2c76c6d58279","title":"马嵬坡","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["旌旗不整奈君何，南去人稀北去多。","尘土已残香粉艳，荔枝犹到马嵬坡。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"惆怅","mood2":[],"scene":[],"cats":{"抒情":["怀古"],"动物":["写马"],"食物":["荔枝"]},"theme_conf":0.662},{"uid":"0d876872-31d8-49d7-a9cf-efbf71e5827b","title":"横吹曲辞 紫骝马","author":"李益","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["争场看鬬鸡，白鼻紫䯄嘶。","漳水春归晚，丛台日向低。","歇鞍珠作汗，试劒玉如泥。","为谢红梁燕，年年妾独栖。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":["春"],"cats":{"抒情":["孤独","闺怨"],"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"d8fe6c90-8cf4-4aa7-ba1d-6b4c2a1f481c","title":"通泉县署屋壁后薛少保画鹤","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["薛公十一鹤，皆写青田真。","画色久欲尽，苍然犹出尘。","低昂各有意，磊落如长人。","佳此志气远，岂惟粉墨新。","万里不以力，群游森会神。","威迟白凤态，非是仓庚邻。","高堂未倾覆，常得慰嘉宾。","曝露墙壁外，终嗟风雨频。","赤霄有真骨，耻饮洿池津。","冥冥任所往，脱略谁能驯。"],"theme":"题画咏艺","theme2":[],"style":"清新","style2":["豪放"],"mood":"欢愉","mood2":[],"scene":["鸟","雨"],"cats":{"动物":["写鸟"]},"theme_conf":0.697},{"uid":"c507b869-c422-46dc-be74-0d9ca10a7217","title":"杜鹃","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["西川有杜鹃，东川无杜鹃。","涪万无杜鹃，云安有杜鹃。","我昔游锦城，结庐锦水边。","有竹一顷余，乔木上参天。","杜鹃暮春至，哀哀叫其间。","我见常再拜，重是古帝魂。","生子百鸟巢，百鸟不敢嗔。","仍为𫗪其子，礼若奉至尊。","鸿雁及羔羊，有礼太古前。","行飞与跪乳，识序如知恩。","圣贤古法则，付与后世传。","君看禽鸟情，犹解事杜鹃。","今忽暮春间，值我病经年。","身病不能拜，泪下如迸泉。"],"theme":"山水田园","theme2":["咏物"],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"抒情":["伤感"],"动物":["写鸟"]},"theme_conf":0.59},{"uid":"ea9ee6ef-9a41-42c5-8676-e47b412f0db9","title":"奉陪郑驸马韦曲二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["韦曲花无赖，家家恼杀人。","绿尊虽尽日，白发好禁春。","石角钩衣破，藤枝刺眼新。","何时占业竹，头戴小乌巾。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"惆怅","mood2":[],"scene":["春"],"cats":{"四季":["春天"],"动物":["写马"]},"theme_conf":0.72},{"uid":"47cb698a-c951-49a4-b17c-032bc033ac87","title":"房兵曹胡马诗","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["胡马大宛名，锋棱瘦骨成。","竹批双耳峻，风入四蹄轻。","所向无空阔，真堪托死生。","骁腾有如此，万里可横行。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["幽峭"],"mood":"悲怆","mood2":[],"scene":[],"cats":{"人生":["战争"],"动物":["写马"]},"theme_conf":0.739},{"uid":"7e75853a-bf7a-4d8d-b3e9-0537f4ed913a","title":"马嵬坡","author":"郑畋","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["[玄]宗回马杨妃死，云雨虽亡日月新。","终是圣明天子事，景阳宫井又何人。"],"theme":"咏史怀古","theme2":[],"style":"悲慨","style2":[],"mood":"悲怆","mood2":[],"scene":["雨","月"],"cats":{"抒情":["怀古"],"动物":["写马"]},"theme_conf":1.0},{"uid":"cpa356df56563a47","title":"双双燕","author":"史达祖","dynasty":"宋","section":"宋词","form":"词","paragraphs":["过春社了，度帘幕中间，去年尘冷。","差池欲住，试入旧巢相并。","还相雕梁藻井。","又软语、商量不定。","飘然快拂花梢，翠尾分开红影。","芳径。","芹泥雨润。","爱贴地争飞，竞夸轻俊。","红楼归晚，看足柳昏花暝。","应自栖香正稳。","便忘了、天涯芳信。","愁损翠黛双蛾，日日画阑独凭。"],"theme":"羁旅思乡","theme2":["闺情宫怨"],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":["孤寂"],"scene":["花"],"cats":{"抒情":["思乡","伤感","孤独","闺怨"],"动物":["写鸟"]},"theme_conf":0.556},{"uid":"ad7a0111-98f9-43e5-bad4-9c73c5336389","title":"归雁","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["闻道今春雁，南归自广州。","见花辞涨海，避雪到罗浮。","是物关兵气，何时免客愁。","年年霜露隔，不过五湖秋。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","秋"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.559},{"uid":"4c9c3d75-272f-4529-bf21-8aafbe5b276e","title":"杂曲歌辞 昔昔盐 那能惜马蹏","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["云中路杳杳，江畔草萋萋。","妾久垂珠泪，君何惜马蹏。","边风悲晓角，营月怨春鼙。","未道休征战，愁眉又复低。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["婉约","悲慨"],"mood":"愁怨","mood2":[],"scene":["春","月","江"],"cats":{"抒情":["伤感"],"四季":["春天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.665},{"uid":"9ce3f413-a677-4e46-a301-43f8be3a40c2","title":"琴曲歌辞 双燕离","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双燕复双燕，双飞令人羡。","玉楼珠阁不独栖，金窗绣户长相见。","柏梁失火去，因入吴王宫。","吴宫又焚荡，雏尽巢亦空。","憔悴一身在，孀雌忆故雄。","双飞难再得，伤我寸心中。"],"theme":"咏物","theme2":["爱情相思","咏史怀古","闲适隐逸"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":[],"scene":["鸟","楼"],"cats":{"抒情":["离别","孤独","怀古"],"动物":["写鸟"]},"theme_conf":0.9},{"uid":"4bb52f17-5109-4d2a-93b9-7e1074dbb45b","title":"酬鸿胪裴主簿雨后睢阳北楼见赠之作","author":"高适","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["暮霞照新晴，归云犹相逐。","有怀晨昏暇，相见登眺目。","问礼侍彤襜，题诗访茅屋。","高楼多古今，陈事满陵谷。","地久微子封，台余孝王筑。","裴回顾霄汉，豁达俯川陆。","远水对秋城，长天向乔木。","公门何清净，列戟森已肃。","不叹携手稀，恒思着鞭速。","终当拂羽翰，轻举随鸿鹄。"],"theme":"寄赠酬答","theme2":[],"style":"清新","style2":["婉约","旷达"],"mood":"惆怅","mood2":[],"scene":["楼"],"cats":{"人生":["梦想"],"动物":["写鸟"]},"theme_conf":0.8},{"uid":"2076be94-1be6-4df6-b8a4-4bd7a755d247","title":"杂曲歌辞 鸣雁行","author":"李白","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["胡雁鸣，辞燕山，昨发委羽朝度关。","一一衔芦枝，南飞散落天地间。","连行接翼往复还，客居烟波寄湘吴。","凌霜触雪毛体枯，畏逢矰缴惊相呼。"],"theme":"咏物","theme2":["咏物"],"style":"旷达","style2":[],"mood":"相思","mood2":[],"scene":["鸟"],"cats":{"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.85},{"uid":"f5e021d7-ea56-4341-947c-8fd024018e1c","title":"走马川行奉送出师西征","author":"岑参","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见走马川行雪海边，平沙莽莽黄入天。","轮台九月风夜吼，一川碎石大如斗，随风满地石乱走。","匈奴草黄马正肥，金山西见烟尘飞。","汉家大将西出师，将军金甲夜不脱。","半夜军行戈相拨，风头如刀面如割。","马毛带雪汗气蒸，五花连钱旋作冰。","幕中草檄砚水凝，虏骑闻之应胆慑。","料知短兵不敢接，车师西门伫献捷。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑"],"mood":"慷慨","mood2":[],"scene":["冬","雪","夜"],"cats":{"动物":["写马"]},"theme_conf":0.554},{"uid":"1f894b7c-19a6-43d2-9f59-2fdc76cf6579","title":"王屋山送道士司马承祯还天台","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["紫府求贤士，清谿祖逸人。","江湖与城阙，异迹且殊伦。","间有幽栖者，居然厌俗尘。","林泉先得性，芝桂欲调神。","地道逾稽岭，天台接海滨。","音徽从此间，万古一芳春。"],"theme":"送别","theme2":["山水田园"],"style":"豪放","style2":["雄浑"],"mood":"惆怅","mood2":[],"scene":["山","楼","江"],"cats":{"动物":["写马"]},"theme_conf":0.379},{"uid":"5901d95d-baf0-46dd-9a29-fd3c020c0a70","title":"相和歌辞 雁门太守行","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["城头月没霜如水，趚趚蹋沙人似鬼。","灯前拭泪试香裘，长引一声残漏子。","驼囊泻酒酒一杯，前头啑血心不回。","寄语年少妻莫哀，鱼金虎竹天上来，雁门山边骨成灰。"],"theme":"羁旅思乡","theme2":["送别"],"style":"沉郁","style2":["婉约"],"mood":"悲怆","mood2":["愁怨"],"scene":["鸟","酒"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.638},{"uid":"aaa3d713-8c7f-4f46-a0d5-39ed552d9511","title":"杂曲歌辞 鸣雁行","author":"韩愈","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["嗷嗷鸣雁鸣且飞，穷秋南去春北归。","去寒就暖识所处，天长地阔栖息稀。","风霜酸苦稻粱微，羽毛摧落身不肥。","徘徊反顾群侣违，哀鸣欲下洲渚非。","江南水阔朝云多，草长沙輭无网罗。"],"theme":"羁旅思乡","theme2":[],"style":"沉郁","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟","江","秋","江南"],"cats":{"抒情":["思乡"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.487},{"uid":"b42b8d7b-3d04-46ed-ba87-11478e25d391","title":"送刘评事充朔方判官赋得征马嘶","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["征马向边州，萧萧嘶不休。","思深应带别，声断为兼秋。","岐路风将远，关山月共愁。","赠君从此去，何日大刀头。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"相思","mood2":["愁怨"],"scene":["秋","月","塞外","山"],"cats":{"抒情":["思念","伤感"],"四季":["秋天"],"动物":["写马"]},"theme_conf":0.479},{"uid":"43d23382-d543-4aba-8a11-ed524328785d","title":"横吹曲辞 紫骝马","author":"卢照邻","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骝马照金鞍，转战入皐兰。","塞门风稍急，长城水正寒。","雪暗鸣珂重，山长喷玉难。","不辞横绝漠，流血几时干。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"慷慨","mood2":[],"scene":["塞外"],"cats":{"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"ed9d64a1-e731-4851-92fa-05556336ef56","title":"奉陪韦润州游鹤林寺","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野寺江城近，双旌五马过。","禅心超忍辱，梵语问多罗。","松林闲僧老，云烟晚日和。","寒塘归路转，清磬隔微波。"],"theme":"佛道禅颂","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","江"],"cats":{"人生":["哲理"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"ccbadda6-7e25-4df6-bde4-cff74e45d080","title":"瘦马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["东郊瘦马使我伤，骨骼硉兀如堵墙。","绊之欲动转敧侧，此岂有意仍腾骧。","细看六印带官字，众道三军遗路旁。","皮干剥落杂泥滓，毛暗萧条连雪霜。","去岁奔波逐余寇，骅骝不惯不得将。","士卒多骑内厩马，惆怅恐是病乘黄。","当时历块误一蹶，委弃非汝能周防。","见人惨澹若哀诉，失主错莫无晶光。","天寒远放雁为伴，日暮不收乌啄疮。","谁家且养愿终惠，更试明年春草长。"],"theme":"羁旅思乡","theme2":["边塞征战","悼亡挽歌"],"style":"幽峭","style2":[],"mood":"惆怅","mood2":["恬淡","悲怆"],"scene":["雪","春"],"cats":{"抒情":["思乡","伤感","悼亡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.371},{"uid":"abf7588f-bae4-41b5-8349-4d593f4a92ae","title":"怀江上（句）（卢延逊五举方登第。〖2〗尝作诗云。「狐冲」二句，租庸张相濬每诵之。又「饿猫」二句，成中令汭激赏之。又「栗爆」二句，王中懿建爱之。卢尝谓人曰：「平生投谒公卿，不意得猫儿狗子之力也。」） 三","author":"卢延让","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["栗爆烧氊破，猫跳触鼎翻。","（《北梦琐言》七、《诗话总龟》三九《诙谐门》。","参见同书八《评论门》引《谈苑》）（〖1〗《怀江上》之题，仅见《谈苑》引，为「饿猫」二句之题，另二联题未详。","〖2〗五举，《北梦琐言》作「二十五举」。","〖3〗「犬刺」，《北梦琐言》作「狗触」。","）。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"山水":["江河"],"动物":["写猫"]},"theme_conf":0.664},{"uid":"5cdca6e7-551e-4198-a27f-f392fafb9d63","title":"白鹭","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["江南渌水多，顾影逗轻波。","落日秦云里，山高奈若何。"],"theme":"山水田园","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江南","江","山"],"cats":{"动物":["写鸟"]},"theme_conf":1.0},{"uid":"495d3ae4-4bc2-46f3-a2bd-1fda9353283f","title":"景龙二年余自门下平章事削阶授江州员外司马寻拜襄州刺史春日赴襄阳途中言志","author":"崔湜","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["余本燕赵人，秉心愚且直。","群籍备所见，孤贞每自饬。","徇禄期代耕，受任亦量力。","幸逢休明时，朝野两荐推。","一朝趋金门，十载奉瑶墀。","入掌迁固笔，出参枚马词。","吏部既三践，中书亦五期。","进无负鼎说，退慙补衮诗。","常恐婴悔吝，不得少酬私。","嗷嗷路傍子，纳谤纷无已。","上动明主疑，下贻大臣耻。","毫发顾无累，冰壶邈自持。","天道何期平，幽冤终见明。","始佐庐陵郡，寻牧襄阳城。","彤帏荷新宠，朱黻蒙旧荣。","力薄慙任重，恩深知命轻。","饬徒留前路，行子悲且慕。","犹闻长乐钟，尚辨青门树。","慈亲不忍诀，昆弟默相顾。","去去勿重陈，川长日云暮。"],"theme":"咏怀抒感","theme2":["应制干谒","闲适隐逸","送别"],"style":"清新","style2":["旷达","沉郁"],"mood":"悲怆","mood2":["孤寂"],"scene":["春","江"],"cats":{"抒情":["伤感","孤独"],"四季":["春天"],"天气":["太阳"],"人物":["母亲"],"人生":["梦想"],"动物":["写马"]},"theme_conf":0.85},{"uid":"06b100d5-9899-4ae0-9eb8-66983943969f","title":"高都护骢马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["安西都护胡青骢，声价歘然来向东。","此马临阵久无敌，与人一心成大功。","功成惠养随所致，飘飘远自流沙至。","雄姿未受伏枥恩，猛气犹思战场利。","腕促蹄高如踣铁，交河几蹴曾冰裂。","五花散作云满身，万里方看汗流血。","长安壮儿不敢骑，走过掣电倾城知。","青丝络头为君老，何由却出横门道。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["豪放"],"mood":"慷慨","mood2":[],"scene":[],"cats":{"人生":["战争"],"动物":["写马"]},"theme_conf":1.0},{"uid":"891b2c80-f3fc-4841-93a9-6d68605e175a","title":"燕衔泥","author":"冯著","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["双燕碌碌飞入屋，屋中老人喜燕归。","裴回绕我床头飞，去年为尔逐黄雀。","雨多屋漏泥土落，尔莫厌老翁茅屋低，梁头作窠梁下栖。","尔不见东家黄鷇鸣啧啧，蛇盘瓦沟鼠穿壁。","豪家大屋尔莫居，娇儿少妇采尔雏。","井旁写水泥自足，衔泥上屋随尔欲。"],"theme":"亲情","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["鸟"],"cats":{"人物":["儿童"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"eebcac54-df54-47a7-9045-aaa691f418ab","title":"杂曲歌辞 昔昔盐 惊魂同夜鹊","author":"赵嘏","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["万里无人见，众情难与论。","思君常入梦，同鹊屡惊魂。","孤寝红罗帐，双嗁玉筯痕。","妾心甘自保，岂复暂忘恩。"],"theme":"游仙梦幻","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["相思"],"scene":["鸟","夜"],"cats":{"抒情":["孤独"],"动物":["写鸟"]},"theme_conf":0.678},{"uid":"2188f98e-d5f0-4740-b94b-e1497a3619ee","title":"黄鹤楼","author":"崔颢","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["昔人已乘白云去，此地空余黄鹤楼。","黄鹤一去不复返，白云千载空悠悠。","晴川历历汉阳树，春草萋萋鹦鹉洲。","日暮乡关何处是，烟波江上使人愁。"],"theme":"羁旅思乡","theme2":["咏史怀古"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["惆怅"],"scene":["楼","江","鸟"],"cats":{"抒情":["思乡","伤感","怀古"],"天气":["写云"],"动物":["写鸟"]},"theme_conf":0.443},{"uid":"9bb05363-395d-48f6-b28a-55d3e414d6cf","title":"杂曲歌辞 发白马","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["将军发白马，旌节渡黄河。","箫鼓聒川岳，沧溟涌洪波。","武安有振瓦，易水无寒歌。","铁骑若雪山，饮流涸滹沱。","扬兵猎月窟，转战畧朝那。","倚剑登燕然，边峰列嵯峨。","萧条万里外，耕作五原多。","一扫清大漠，包虎戢金戈。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["雄浑","清新"],"mood":"慷慨","mood2":[],"scene":["山","江","雪","塞外","月"],"cats":{"山水":["黄河"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.777},{"uid":"feb085bc-e461-4a18-b787-e831e3ef1885","title":"宿庐山赠白鹤观刘尊师","author":"包佶","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["苍苍五老雾中坛，杳杳三山洞里官。","手护昆仑象牙简，心推霹雳枣枝盘。","春飞雪粉如毫润，晓漱琼膏冰齿寒。","渐恨流年筋力少，惟思露冕事星冠。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["清新","雄浑"],"mood":"愁怨","mood2":[],"scene":["山","雪"],"cats":{"山水":["庐山"],"天气":["写雪"],"人生":["时光"],"动物":["写鸟"]},"theme_conf":0.72},{"uid":"827e44b1-7064-4ff7-9a9c-192eece94e2d","title":"韦讽录事宅观曹将军画马图","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["国初已来画鞍马，神妙独数江都王。","将军得名三十载，人间又见真乘黄。","曾貌先帝照夜白，龙池十日飞霹雳。","内府殷红马脑盌，倢伃传诏才人索。","盌赐将军拜舞归，轻纨细绮相追飞。","贵戚权门得笔迹，始觉屏障生光辉。","昔日太宗拳毛䯄，近时郭家师子花。","今之新图有二马，复令识者久叹嗟。","此皆骑战一敌万，缟素漠漠开风沙。","其余七匹亦殊绝，迥若寒空动烟雪。","霜蹄蹴踏长楸间，马官厮养森成列。","可怜九马争神骏，顾视清高气深稳。","借问苦心爱者谁，后有韦讽前支遁。","忆昔巡幸新丰宫，翠华拂天来向东。","腾骧磊落三万匹，皆与此图筋骨同。","自从献宝朝河宗，无复射蛟江水中。","君不见金粟堆前松柏里，龙媒去尽鸟呼风。"],"theme":"边塞征战","theme2":["题画咏艺"],"style":"绮丽","style2":["清新"],"mood":"孤寂","mood2":["相思"],"scene":["雪","塞外"],"cats":{"抒情":["思念","孤独"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.481},{"uid":"aab2f610-6652-486f-bbc7-034366eb35a4","title":"咏饮马","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["骏骨饮长泾，奔流洒络缨。","细纹连喷聚，乱荇绕蹄萦。","水光鞍上侧，马影溜中横。","翻似天池里，腾波龙种生。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"动物":["写马"]},"theme_conf":1.0},{"uid":"cac5a624-4332-4200-9b3d-735cb790e16d","title":"中和节赐百官燕集因示所怀","author":"德宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["至化恒在宥，保和兹息人。","推诚抚诸夏，与物长为春。","仲月风景暖，禁城花柳新。","芳时协金奏，赐宴同群臣。","丝竹岂云乐，忠贤惟所亲。","庶洽朝野意，旷然天地均。"],"theme":"应制干谒","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["鸟","夏","花","春","月"],"cats":{"四季":["春天","夏天"],"动物":["写鸟"]},"theme_conf":0.86},{"uid":"1c1ac9e3-ae77-47b4-a501-ab9ca2eb84bc","title":"和马郎中移白菊见示","author":"李商隐","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["陶诗只采黄金宝，郢曲新传白雪英。","素色不同篱下发，繁花疑自月中生。","浮杯小摘开云母，带露全移缀水精。","偏称含香五字客，从兹得地始芳荣。"],"theme":"咏物","theme2":[],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["花","雪","重阳"],"cats":{"节日":["重阳节"],"动物":["写马"],"植物":["菊花"]},"theme_conf":0.86},{"uid":"16986240-98d2-47da-a4a9-cf487c2c2f0e","title":"鸥","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["江浦寒鸥戏，无他亦自饶。","却思飜玉羽，随意点春苗。","雪暗还须浴，风生一任飘。","几群沧海上，清影日萧萧。"],"theme":"山水田园","theme2":[],"style":"旷达","style2":[],"mood":"恬淡","mood2":[],"scene":["江","雪","春"],"cats":{"四季":["春天"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"8944162e-0986-4d0b-b9f9-ce0b899c0298","title":"相和歌辞 饮马长城窟行","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["驰马渡河干，流深马渡难。","前逢锦车使，都护在楼兰。","轻骑犹衔勒，疑兵尚解鞍。","温池下绝涧，栈道接危峦。","拓地勋未赏，亡城律讵宽。","有月关犹暗，经春陇尚寒。","云昏无复影，冰合不闻湍。","怀君不可遇，聊持报一餐。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":["春","楼","月"],"cats":{"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.821},{"uid":"cpeee94b3a49dd8c","title":"宴山亭・燕山亭","author":"张","dynasty":"宋","section":"宋词","form":"词","paragraphs":["幽梦初回，重阴未开，晓色吹成疏雨。","竹槛气寒，蕙畹声摇，新绿暗通南浦。","未有人行，才半启、回廊朱户。","无绪。","空望极霓旌，锦书难据。","苔径追忆曾游，念谁伴、秋千采绳芳柱。","犀奁黛卷，凤枕云孤，应也几番凝伫。","怎得伊来，花雾绕、小堂深处。","留住。","直到老、不教归去。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"相思","mood2":["孤寂","欢愉"],"scene":["山","园林","楼","鸟","花"],"cats":{"抒情":["离别","思念","孤独"],"动物":["写鸟"]},"theme_conf":0.579},{"uid":"1fe5f4d5-0d7b-41c2-a122-7fdcc3cfaabb","title":"怀江上（句）（卢延逊五举方登第。〖2〗尝作诗云。「狐冲」二句，租庸张相濬每诵之。又「饿猫」二句，成中令汭激赏之。又「栗爆」二句，王中懿建爱之。卢尝谓人曰：「平生投谒公卿，不意得猫儿狗子之力也。」） 二","author":"卢延让","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["饿猫临鼠穴，馋犬舐鱼砧。"],"theme":"民生疾苦","theme2":[],"style":"沉郁","style2":[],"mood":"欢愉","mood2":[],"scene":["江"],"cats":{"动物":["写猫"]},"theme_conf":0.603},{"uid":"13f88c40-f660-4910-8d8c-7c29cfcd416e","title":"相和歌辞 饮马长城窟行","author":"僧子兰","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["游客长城下，饮马长城窟。","马嘶闻水腥，为浸征人骨。","岂不是流泉，终不成潺湲。","洗尽骨上土，不洗骨中冤。","骨若比流水，四海有还魂。","空流呜咽声，声中疑是言。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":[],"mood":"慷慨","mood2":[],"scene":[],"cats":{"动物":["写马"]},"theme_conf":0.661},{"uid":"0cc77a07-c1db-4875-9e12-9574e51aab15","title":"荆南兵马使太常卿赵公大食刀歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["太常楼船声嗷嘈，问兵刮寇趋下牢。","牧出令奔飞百艘，猛蛟突兽纷腾逃。","白帝寒城驻锦袍，玄冬示我胡国刀。","壮士短衣头虎毛，凭轩拔鞘天为高。","翻风转日木怒号，冰翼雪澹伤哀猱。","镌错碧甖䴙鹈膏，铓锷已莹虚秋涛。","鬼物撇捩辞坑壕，苍水使者扪赤条。","龙伯国人罢钓鼇，芮公回首颜色劳。","分阃救世用贤豪，赵公玉立高歌起。","揽环结佩相终始，万岁持之护天子。","得君乱丝与君理，蜀江如线如针水。","荆岑弹丸心未已，贼臣恶子休干纪。","魑魅魍魉徒为耳，妖腰乱领敢欣喜。","用之不高亦不庳，不似长劒须天倚。","吁嗟光禄英雄弭，大食宝刀聊可比。","丹青宛转麒麟里，光芒六合无泥滓。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["悲慨","幽峭"],"mood":"慷慨","mood2":[],"scene":["冬","楼"],"cats":{"四季":["冬天"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.805},{"uid":"26a0266d-313c-4911-b629-2418556d1b03","title":"洗兵马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["中兴诸将收山东，捷书日报清昼同。","河广传闻一苇过，胡危命在破竹中。","祗残邺城不日得，独任朔方无限功。","京师皆骑汗血马，回纥喂肉葡萄宫。","已喜皇威清海岱，常思仙仗过崆峒。","三年笛里关山月，万国兵前草木风。","成王功大心转小，郭相谋深古来少。","司徒清鉴悬明镜，尚书气与秋天杳。","二三豪俊为时出，整顿乾坤济时了。","东走无复忆鲈鱼，南飞觉有安巢鸟。","青春复随冠冕入，紫禁正耐烟花绕。","鹤禁通霄凤辇备，鸡鸣问寝龙楼晓。","攀龙附凤势莫当，天下尽化为侯王。","汝等岂知蒙帝力，时来不得夸身强。","关中既留萧丞相，幕下复用张子房。","张公一生江海客，身长九尺须眉苍。","征起适遇风云会，扶颠始知筹策良。","青袍白马更何有，后汉今周喜再昌。","寸地尺天皆入贡，奇祥异瑞争来送。","不知何国致白环，复道诸山得银瓮。","隐士休歌紫芝曲，词人解撰河清颂。","田家望望惜雨干，布谷处处催春种。","淇上健儿归莫嬾，城南思妇愁多梦。","安得壮士挽天河，净洗甲兵长不用。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["旷达","清新"],"mood":"欢愉","mood2":["相思"],"scene":["鸟","春"],"cats":{"抒情":["思念"],"四季":["春天"],"人生":["青春","战争"],"动物":["写马"]},"theme_conf":0.43},{"uid":"ccd8a969-3713-4066-b890-ead4d4fb7b6e","title":"送岳州司马弟之任","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["岳阳天水外，念尔一帆过。","野墅人烟逈，山城雁影多。","有时巫峡色，终日洞庭波。","丞相今为郡，应无劳者歌。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江","舟","山","鸟","园林"],"cats":{"动物":["写马"]},"theme_conf":1.0},{"uid":"6b7a1754-680e-4488-be9b-d530ede678b6","title":"琴曲歌辞 司马相如琴歌","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["凤兮凤兮非无凰，山重水阔不可量。","梧桐结阴在朝阳，濯羽弱水鸣高翔。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":["山"],"cats":{"动物":["写马"]},"theme_conf":0.657},{"uid":"cd3d8e0c-a549-44a9-b55c-4f1c9b9befed","title":"秋霖中奉裴令公见招早出赴会马上先寄六韵","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["雨暗三秋日，泥深一尺时。","老人平旦出，自问欲何之。","不是寻医药，非干送别离。","素书传好语，绛帐赴佳期。","续借桃花马，催迎杨柳姬。","只愁张录事，罚我怪来迟。"],"theme":"寄赠酬答","theme2":[],"style":"沉郁","style2":["幽峭"],"mood":"愁怨","mood2":[],"scene":["秋","雨"],"cats":{"抒情":["离别","伤感"],"四季":["秋天"],"天气":["写雨"],"人物":["老师"],"动物":["写马"]},"theme_conf":0.88},{"uid":"f3c25a75-6445-47e0-a5ae-265559f9f990","title":"越燕二首 二","author":"李商隐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["将泥红蓼岸，得草绿杨村。","命侣添新意，安巢复旧痕。","去应逢阿母，来莫害王孙。","记取丹山凤，今为百鸟尊。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","江南"],"cats":{"人物":["母亲"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"6dcc533e-01af-48f9-835f-47f087bc81c7","title":"酬李二十二兄主簿马迹山见寄","author":"权德舆","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["杳杳尘外想，悠悠区中缘。","如何战未胜，曾是教所牵。","远郊有灵峰，夙昔栖真仙。","鸾声去已久，马迹空依然。","丹崖转初旭，碧落凝秋烟。","松风共箫飒，萝月想婵娟。","内兄蕴遐心，嘉遯性所便。","不能栖枳棘，且复探云泉。","中有冥寂人，闲读逍遥篇。","联袂共支[策]，抠衣赏绝编。","徐行石上苔，静韵风中弦。","烟霞湿儒服，日月生寥天。","新诗来起予，璀璨六义全。","能尽含写意，转令山水鲜。","若闻笙鹤声，宛在耳目前。","登攀阻心赏，愁绝空怀贤。","出处岂异途，心冥即真筌。","𫏐从西府檄，终卧东菑田。","不嫌予步蹇，但恐君行膻。","如能固旷怀，谷口期穷年。"],"theme":"山水田园","theme2":["送别"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":["恬淡","愁怨"],"scene":["山"],"cats":{"抒情":["伤感"],"天气":["月亮"],"节日":["中秋节"],"动物":["写马"]},"theme_conf":0.457},{"uid":"3383ff3c-b6bf-44b6-900a-766acc558644","title":"王兵马使二角鹰","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["悲台萧飒石巃嵸，哀壑杈枒浩呼汹。","中有万里之长江，回风滔日孤光动。","角鹰飜倒壮士臂，将军玉帐轩翠气。","二鹰猛脑徐侯穟，目如愁胡视天地。","杉鸡竹兔不自惜，溪虎野羊俱辟易。","鞲上锋棱十二翮，将军勇锐与之敌。","将军树勋起安西，昆仑虞泉入马蹄。","白羽曾肉三狻猊，敢决岂不与之齐。","荆南芮公得将军，亦如角鹰下翔云。","恶鸟飞飞啄金屋，安得尔辈开其群，驱出六合枭鸾分。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"悲怆","mood2":["慷慨"],"scene":["江"],"cats":{"抒情":["伤感"],"山水":["长江"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.518},{"uid":"19a60c13-e4f4-4653-8262-70e474cc636a","title":"景龙四年正月五日移仗蓬莱宫御大明殿会吐蕃骑马之戏因重为柏梁体联句","author":"中宗皇帝","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["大明御宇临万方，顾慙内政翊陶唐。","鸾鸣凤舞向平阳，秦楼鲁馆沐恩光。","无心为子辄求郎，雄才七步谢陈王。","当熊让辇媿前芳，再司铨筦恩可忘。","文江学海思济航，万邦考绩臣所详。","著作不休出中肠，权豪屏迹肃严霜。","铸鼎开岳造明堂，玉醴由来献寿觞。"],"theme":"游仙梦幻","theme2":[],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["月","酒"],"cats":{"天气":["月亮"],"动物":["写马"]},"theme_conf":1.0},{"uid":"c50ef689-8ad8-43b3-8504-54a2a5a54171","title":"奉陪郑驸马韦曲二首 二","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["野寺垂杨里，春畦乱水间。","美花多映竹，好鸟不归山。","城郭终何事，风尘岂驻颜。","谁能共公子，薄暮欲俱还。"],"theme":"哲理悟道","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"97384a23-7f75-4d43-baee-ac6c4a6c6d14","title":"柳司马至","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["有使归三峡，相过问两京。","函关犹出将，渭水更屯兵。","设备邯郸道，和亲逻些城。","幽燕唯鸟去，商洛少人行。","衰谢身何补，萧条病转婴。","霜天到宫阙，恋主寸心明。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":[],"mood":"慷慨","mood2":[],"scene":["鸟"],"cats":{"动物":["写马"],"植物":["柳树"]},"theme_conf":1.0},{"uid":"48568d08-d789-4eca-b9a8-5dcf09d6a516","title":"李鄠县丈人胡马行","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["丈人骏马名胡骝，前年避胡过金牛。","回鞭却走见天子，朝饮汉水暮灵州。","自矜胡骝奇绝代，乘出千人万人爱。","一闻说尽急难材，转益愁向驽骀辈。","头上锐耳批秋竹，脚下高蹄削寒玉。","始知神龙别有种，不比俗马空多肉。","洛阳大道时再清，累日喜得俱东行。","凤臆龙鬐未易识，侧身注目长风生。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["绮丽","沉郁"],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["秋"],"cats":{"抒情":["伤感"],"四季":["秋天"],"动物":["写马"]},"theme_conf":0.775},{"uid":"1ea9b354-24bc-497a-a8fb-0e83e0a00c9f","title":"答司马承祯上劒镜","author":"明皇帝","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["宝照含天地，神劒合阴阳。","日月丽光景，星斗裁文章。","写鉴表容质，佩服为身防。","从兹一赏玩，永德保龄长。"],"theme":"寄赠酬答","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["月"],"cats":{"动物":["写马"]},"theme_conf":0.9},{"uid":"8a1b96b6-a498-472c-95ea-db26750163f8","title":"送深州吴司马归使幕","author":"韩翃","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["东门送远客，车马正纷纷。","旧识张京兆，新随刘领军。","行骢看暮雨，归雁踏青云。","一去藂台北，佳声几日闻。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["江南","清明","雨"],"cats":{"节日":["清明节"],"动物":["写马"]},"theme_conf":0.55},{"uid":"ea82076e-44f8-4d9c-8844-a2325b642224","title":"题鹤林寺","author":"薛据","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["道门隐形胜，向背临法桥。","松覆山殿冷，花藏溪路遥。","珊珊宝幡挂，燄燄明灯烧。","迟日半空谷，春风连上潮。","少凭水木兴，暂忝身心调。","愿谢携手客，兹山禅侣饶。"],"theme":"山水田园","theme2":["哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["鸟","春","山","江"],"cats":{"四季":["春天"],"人生":["哲理"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.533},{"uid":"5a5dcd73-11dd-46df-9eb3-e345148ad909","title":"故燕国相公挽歌二首 二","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["共美持衡日，皆言折槛时。","蜀侯供庙略，汉主缺台司。","车马行仍止，笳箫咽又悲。","今年杜陵陌，殄瘁百花迟。"],"theme":"悼亡挽歌","theme2":[],"style":"清新","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"抒情":["伤感","悼亡"],"动物":["写鸟"]},"theme_conf":0.98},{"uid":"757a180d-55eb-4931-9f10-c71649f6a06d","title":"秋日过鸿举法师寺院便送归江陵","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["看画长廊遍，寻僧一径幽。","小池兼鹤净，古木带蝉秋。","客至茶烟起，禽归讲席收。","浮杯明日去，相望水悠悠。"],"theme":"送别","theme2":["咏史怀古","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["秋","园林"],"cats":{"抒情":["怀古"],"四季":["秋天"],"天气":["太阳"],"人物":["老师"],"动物":["写鸟"]},"theme_conf":0.28},{"uid":"cp897e2c6cf08579","title":"瑞鹤仙","author":"吴文英","dynasty":"宋","section":"宋词","form":"词","paragraphs":["晴丝牵绪乱。","对沧江斜日，花飞人远。","垂杨暗吴苑。","正旗亭烟冷，河桥风暖。","兰情蕙盼。","惹相思、春根酒畔。","又争知、吟骨萦销，渐把旧衫重翦。","凄断。","流红千浪，缺月孤楼，总难留燕。","歌尘凝扇。","待凭信，拌分钿。","试挑灯欲写，还依不忍，笺幅偷和泪卷。","寄残云、剩雨蓬莱，也应梦见。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":["清新"],"mood":"相思","mood2":["愁怨"],"scene":["鸟","楼"],"cats":{"抒情":["思念","伤感"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":0.503},{"uid":"cp4189bec3f75298","title":"瑞鹤仙","author":"蒋捷","dynasty":"宋","section":"宋词","form":"词","paragraphs":["绀烟迷雁迹。","渐断鼓零钟，街喧初息。","风檠背寒壁。","放冰蜍飞到，丝丝窗隙。","琼瑰暗泣。","念乡关、霜芜似织。","漫将身、化鹤归来，忘却旧游端的。","欢极。","蓬壶蕖浸，花院梨溶，醉连春夕。","柯云罢弈。","樱桃在，梦难觅。","劝清光，乍可幽窗相伴，休照红楼夜笛。","怕人间、换谱伊凉，素娥未识。"],"theme":"羁旅思乡","theme2":["闲适隐逸","游仙梦幻"],"style":"旷达","style2":["清新"],"mood":"悲怆","mood2":["欢愉","相思"],"scene":["鸟"],"cats":{"抒情":["思乡"],"动物":["写鸟"]},"theme_conf":0.457},{"uid":"19b577a6-dca0-4c95-9365-7e4a8356e71d","title":"郑驸马池台喜遇郑广文同饮","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["不谓生戎马，何知共酒杯。","然脐郿坞败，握节汉臣回。","白发千茎雪，丹心一寸灰。","别离经死地，披写忽登台。","重对秦箫发，俱过阮宅来。","留连春夜舞，泪落强裴回。"],"theme":"送别","theme2":[],"style":"婉约","style2":["沉郁"],"mood":"欢愉","mood2":[],"scene":["酒","楼","园林","雪","春"],"cats":{"抒情":["离别"],"四季":["春天"],"动物":["写马"]},"theme_conf":1.0},{"uid":"09788f19-1e11-4394-a543-0edf2cfdcae9","title":"相和歌辞 燕歌行","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["汉家烟尘在东北，汉将辞家破残贼。","男儿本自重横行，天子非常赐颜色。","𪭢金伐鼓下榆关，旌旗逶迤碣石间。","校尉羽书飞瀚海，单于猎火照狼山。","山川萧条极边土，胡骑凭凌杂风雨。","战士军前半死生，美人帐下犹歌舞。","大漠穷秋塞草衰，孤城落日鬬兵稀。","身当恩遇常轻敌，力尽关山未解围。","铁衣远戍辛勤久，玉箸应啼别离后。","少妇城南欲断肠，征人蓟北空回首。","边风飘飘那可度，绝域苍茫更何有。","杀气三日作阵云，寒声一夜传刁斗。","相看白刃血纷纷，死节从来岂顾勋。","君不见沙场征战苦，至今犹忆李将军。"],"theme":"边塞征战","theme2":[],"style":"雄浑","style2":["沉郁","婉约"],"mood":"孤寂","mood2":["愁怨","相思"],"scene":["塞外"],"cats":{"抒情":["离别","思念","伤感","孤独"],"人物":["女子"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.755},{"uid":"0f1e20b5-a8e4-45cd-a1e2-45710eec46fb","title":"横吹曲辞 骢马曲","author":"纪唐天","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["连钱出塞蹋沙蓬，岂比当时御史骢。","逐北自谙深碛路，连嘶谁念静边功。","登山每与青云合，弄影应知碧草同。","今日虏平将换妾，不如罗袖舞春风。"],"theme":"边塞征战","theme2":["闺情宫怨"],"style":"豪放","style2":[],"mood":"恬淡","mood2":[],"scene":["塞外","春","山"],"cats":{"抒情":["闺怨"],"四季":["春天"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.63},{"uid":"78f8699c-a199-4dde-8be3-79fb887a596d","title":"相和歌辞 门有车马客行","author":"李白","dynasty":"唐","section":"唐诗","form":"乐府","paragraphs":["门有车马客，金鞍曜朱轮。","谓从丹霄落，乃是故乡亲。","呼儿埽中堂，坐客论悲辛。","对酒两不饮，停觞泪盈巾。","叹我万里游，飘飖三十春。","空谈霸王略，紫绶不挂身。","雄劒藏玉匣，阴符生素尘。","廓落无所合，流离湘水滨。","借问宗党间，多为泉下人。","生苦百战役，死托万鬼邻。","北风扬胡沙，埋翳周与秦。","大运且如此，苍穹宁匪仁。","恻怆竟何道？存亡任大钧。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"豪放","style2":["绮丽","冲淡"],"mood":"悲怆","mood2":["愁怨"],"scene":["酒"],"cats":{"抒情":["思乡","伤感","悼亡"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.438},{"uid":"d43a4767-2240-44b7-8d5b-c2acdc689839","title":"黄鹤楼送孟浩然之广陵","author":"李白","dynasty":"唐","section":"唐诗","form":"七言绝句","paragraphs":["故人西辞黄鹤楼，烟花三月下扬州。","孤帆远影碧山尽，唯见长江天际流。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["楼","江"],"cats":{"抒情":["友情","孤独"],"山水":["长江"],"动物":["写鸟"]},"theme_conf":0.73},{"uid":"34751bd9-cc56-4d97-b75a-ff8665fd9b27","title":"鹦鹉猫儿篇","author":"阎朝隐","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["霹雳引，丰隆鸣，猛兽噫气蛇吼声。","鹦鹉鸟，同资造化兮殊粹精。","鹔鹴毛，翡翠翼。","鹓雏延颈，鹍鸡弄色。","鹦鹉鸟，同禀阴阳兮异埏埴。","彼何为兮，隐隐振振。","此何为兮，绿衣翠襟。","彼何为兮，窘窘蠢蠢。","此何为兮，好貌好音。","彷彷兮徉徉，似妖姬躧步兮动罗裳。","趋趋兮跄跄，若处子回眸兮登玉堂。","爰有兽也，安其忍，觜其脇，距其胸，与之放旷浪浪兮，从从容容。","钩爪锯牙也，宵行昼伏无以当，遇之兮忘味。","抟击腾掷也，朝飞暮噪无以拒，逢之兮屏气。","由是言之，贪残薄则智慧作，贪残临之兮不复攫。","由是言之，智慧周则贪残囚，智慧犯之兮不复忧。","菲形陋质虽贱微，皇王顾遇长光辉。","离宫别馆临朝市，妙舞繁弦杂宫征。","嘉喜堂前景福内，合欢殿上明光里。","云母屏风文彩合，流苏斗帐香烟起。","承恩宴盼接宴喜，高视七头金骆驼。","平怀五尺铜狮子，国有君兮国有臣。","君为主兮臣为宾，朝有贤兮朝有德。","贤为君兮德为饰，千年万岁兮心转忆。"],"theme":"送别","theme2":[],"style":"绮丽","style2":[],"mood":"欢愉","mood2":[],"scene":[],"cats":{"抒情":["离别"],"动物":["写猫"]},"theme_conf":1.0},{"uid":"a2a74e95-00c2-4dce-a38e-6a4ec4a8923d","title":"赠别张驸马","author":"戎昱","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["上元年中长安陌，见君朝下欲归宅。","飞龙骑马三十匹，玉勒雕鞍照初日。","数里衣香遥扑人，长衢雨歇无纤尘。","从奴斜抱𠡠赐锦，双双蹙出金麒麟。","天子爱壻皇后弟，独步明时负权势。","一身扈跸承殊泽，甲第朱门耸高戟。","凤凰楼上伴吹箫，鹦鹉杯中醉留客。","泰去否来何足论，宫中晏驾人事翻。","一朝负谴辞丹阙，五年待罪湘江源。","冠冕凄凉几迁改，眼看桑田变成海。","华堂金屋别赐人，细眼黄头总何在。","渚宫相见寸心悲，嬾欲今时问昔时。","看君风骨殊未歇，不用愁来双泪垂。"],"theme":"送别","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"愁怨","mood2":[],"scene":["酒","元宵","江"],"cats":{"抒情":["离别","伤感"],"节日":["元宵节"],"动物":["写马"]},"theme_conf":0.579},{"uid":"dd40f188-e63b-48e7-9418-7e8e667b7308","title":"送陆鸿渐栖霞寺采茶","author":"皇甫冉","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["采茶非采菉，远远上层崖。","布叶春风暖，盈筐白日斜。","旧知山寺路，时宿野人家。","借问王孙草，何时泛椀花。"],"theme":"送别","theme2":["闲适隐逸","哲理悟道"],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["春","山"],"cats":{"四季":["春天"],"动物":["写鸟"],"食物":["写茶"]},"theme_conf":0.376},{"uid":"2656cc2f-8178-477d-88b4-13bb0d73a634","title":"崔司录宅燕大理李卿","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["多雨殊未已，秋云更沈沈。","洛阳故人初解印，山东小吏来相寻。","上卿才大名不朽，早朝至尊暮求友。","豁达常推海内贤，殷勤但酌尊中酒。","饮醉欲言归剡溪，门前驷马光照衣。","路傍观者徒唧唧，我公不以为是非。"],"theme":"寄赠酬答","theme2":["山水田园","应制干谒"],"style":"豪放","style2":["清新"],"mood":"恬淡","mood2":[],"scene":["酒"],"cats":{"抒情":["友情"],"动物":["写鸟"]},"theme_conf":0.68},{"uid":"057c887c-9525-4a2e-b553-23d5afab9275","title":"病马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["乘尔亦已久，天寒关塞深。","尘中老尽力，岁晚病伤心。","毛骨岂殊众，驯良犹至今。","物微意不浅，感动一沈吟。"],"theme":"咏物","theme2":["边塞征战"],"style":"沉郁","style2":[],"mood":"孤寂","mood2":[],"scene":["塞外"],"cats":{"生活":["边塞"],"动物":["写马"]},"theme_conf":0.621},{"uid":"f5c7c474-4fff-4fec-9f4a-d8e2d1447a77","title":"送翰林张司马南海勒碑","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["冠冕通南极，文章落上台。","诏从三殿去，碑到百蛮开。","野馆浓花发，春帆细雨来。","不知沧海上，天遣几时回。"],"theme":"送别","theme2":["咏史怀古"],"style":"豪放","style2":[],"mood":"惆怅","mood2":[],"scene":["雨"],"cats":{"抒情":["怀古"],"天气":["写雨"],"动物":["写马"]},"theme_conf":0.509},{"uid":"c2232345-1eea-47ab-b252-bc20d75b246f","title":"自江州司马授忠州刺史仰荷圣泽聊书鄙诚","author":"白居易","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["炎瘴抛身远，泥涂索脚难。","网初鳞拨剌，笼久翅摧残。","雷电颁时令，阳和变岁寒。","遗簪承旧念，剖竹授新官。","乡觉前程近，心随外事宽。","生还应有分，西笑问长安。"],"theme":"应制干谒","theme2":["山水田园"],"style":"清新","style2":[],"mood":"欢愉","mood2":[],"scene":["夏","江"],"cats":{"四季":["夏天"],"动物":["写马"],"植物":["荷花"]},"theme_conf":0.78},{"uid":"cp17149d5a941159","title":"瑞鹤仙","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["悄郊原带郭。","行路永，客去车尘漠漠。","斜阳映山落。","敛馀红、犹恋孤城栏角。","凌波步弱。","过短亭、何用素约。","有流莺劝我，重解绣鞍，缓引春酌。","不记归时早暮，上马谁扶，醒眠朱阁。","惊飙动幕。","扶残醉，绕红药。","叹西园、已是花深无地，东风何事又恶。","任流光过却。","犹喜洞天自乐。"],"theme":"游仙梦幻","theme2":[],"style":"沉郁","style2":["绮丽"],"mood":"欢愉","mood2":[],"scene":["春","鸟","酒","楼","塞外"],"cats":{"四季":["春天"],"动物":["写鸟"]},"theme_conf":0.669},{"uid":"d8ff176a-ba69-4277-a54e-9e515bc19304","title":"相和歌辞 雁门太守行","author":"李贺","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["黑云压城城欲摧，甲光向月金鳞开。","角声满天秋色里，塞上燕支凝夜紫。","半卷红旗临易水，霜重鼓寒声不起。","报君黄金台上意，提携玉龙为君死。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟","秋"],"cats":{"四季":["秋天"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.658},{"uid":"31bc78e4-ece6-4a4f-b5bb-a8c00df6c620","title":"杂曲歌辞 鸣雁行","author":"陆龟蒙","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["朔风动地来，吹起沙上声。","闺中有边思，玉筯此时横。","莫怕儿女恨，主人烹不鸣。"],"theme":"羁旅思乡","theme2":["闺情宫怨","亲情"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟","冬"],"cats":{"抒情":["思乡","闺怨"],"四季":["冬天"],"天气":["写风"],"动物":["写鸟"]},"theme_conf":0.41},{"uid":"b39a2f1c-b07b-43c6-8f88-fa8ef3b06e4b","title":"相和歌辞 飞来双白鹤","author":"虞世南","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["飞来双白鹤，奋翼远凌烟。","双栖集紫盖，一举背青田。","飏影过伊洛，流声入管弦。","鸣群倒景外，刷羽阆风前。","映海疑浮雪，拂涧泻飞泉。","燕雀宁知去，蜉蝣不识还。","何言别俦侣，从此间山川。","顾步已相失，裴回反自怜。","危心犹警露，哀响讵闻天。","无因振六翮，轻举复随仙。"],"theme":"山水田园","theme2":["送别"],"style":"清新","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"动物":["写鸟"]},"theme_conf":0.623},{"uid":"49016fc5-51cc-4d01-896d-a6e14768ce6e","title":"横吹曲辞 紫骝马","author":"李白","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["紫骝行且嘶，双飜碧玉蹄。","临流不肎渡，似惜锦障泥。","白雪关山远，黄云海树迷。","挥鞭万里去，安得念春闺。"],"theme":"羁旅思乡","theme2":["边塞征战"],"style":"绮丽","style2":["豪放"],"mood":"相思","mood2":[],"scene":["雪","春","塞外","山"],"cats":{"抒情":["思乡"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.358},{"uid":"4c91b589-bd48-42db-8034-5b8c236dd885","title":"琴曲歌辞 别鹤","author":"杜牧","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["分飞共所从，六翮势摧风。","声断碧云外，影孤明月中。","青田归路远，月桂旧巢空。","矫翼知何处，天涯不可穷。"],"theme":"送别","theme2":[],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["月"],"cats":{"抒情":["离别","孤独"],"天气":["月亮"],"动物":["写鸟"]},"theme_conf":0.534},{"uid":"0ef99715-15ba-4586-98d0-bb90aece4b71","title":"杂曲歌辞 鸣雁行","author":"鲍溶","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["七月朔方雁心苦，联影翻空落南土。","八月江南阴复晴，浮云绕天难夜行。","羽翼劳痛心虚惊，一声相呼百处鸣。","楚童夜宿烟波侧，沙上布罗连草色。","月暗风悲欲下天，不知何处容栖息？","楚童胡为伤我神，尔不曾作远行人。","江南羽族本不少，宁得网罗此客鸟。"],"theme":"羁旅思乡","theme2":[],"style":"冲淡","style2":["悲慨"],"mood":"悲怆","mood2":[],"scene":["鸟","江","江南"],"cats":{"抒情":["思乡","伤感"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.745},{"uid":"1bba0f29-6b38-446b-98d5-20268903330c","title":"琴曲歌辞 别鹤","author":"张籍","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["双鹤出云谿，分飞各自迷。","空巢在松杪，折羽落江泥。","寻水终不饮，逢林亦未栖。","别离应易老，万里两凄凄。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"愁怨","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别"],"动物":["写鸟"]},"theme_conf":0.671},{"uid":"0919893a-6302-4409-87ac-c1208e2e2f87","title":"横吹曲辞 骢马","author":"李群玉","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["浮云何权奇，绝足势未知。","长嘶青海风，躞蹀振云丝。","由来渥洼种，本是苍龙儿。","穆满不再活，无人昆阆骑。","君识跃峤怯，宁劳耀金羁。","青刍与白水，空笑驽骀肥。","伯乐傥一见，应惊耳长垂。","当思八荒外，逐日向瑶池。"],"theme":"边塞征战","theme2":["羁旅思乡"],"style":"豪放","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":[],"cats":{"抒情":["思乡","孤独"],"动物":["写马"]},"theme_conf":0.577},{"uid":"b84b8b0b-9447-467f-819f-0ddf0f00a03a","title":"相和歌辞 饮马长城窟行","author":"王翰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["长安少年无远图，一生惟羡执金吾。","骐𬴊前殿拜天子，走马为君西击胡。","胡沙猎猎吹人面，汉虏相逢不相见。","遥闻鼙鼓动地来，传道单于夜犹战。","此时顾恩宁顾身，为君一行摧万人。","壮士挥戈回白日，单于溅血染朱轮。","回来饮马长城窟，长安道傍多白骨。","问之耆老何代人，云是秦王筑城卒。","黄昏塞北无人烟，鬼哭啾啾声沸天。","无罪见诛功不赏，孤魂流落此城边。","当昔秦王按劒起，诸侯膝行不敢视。","富国彊兵二十年，筑怨兴徭九千里。","秦王筑城何太愚，天实亡秦非北胡。","一朝祸起萧墙内，渭水咸阳不复都。"],"theme":"边塞征战","theme2":[],"style":"沉郁","style2":["悲慨"],"mood":"孤寂","mood2":["悲怆"],"scene":["夜","塞外"],"cats":{"抒情":["孤独"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.803},{"uid":"d5082efe-beda-482e-8f57-f88241cdda54","title":"奉陪韦中丞使君游鹤林寺","author":"皇甫曾","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["古寺传灯久，层城闭阁闲。","香花同法侣，旌斾入深山。","寒磬虚空里，孤云起灭间。","谢公忆高卧，徒御欲东还。"],"theme":"哲理悟道","theme2":["山水田园","应制干谒"],"style":"冲淡","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟","花","楼","山"],"cats":{"抒情":["孤独"],"动物":["写鸟"]},"theme_conf":0.37},{"uid":"e3c39438-5647-430e-b814-1318cde0ffb1","title":"琴曲歌辞 别鹤","author":"王建","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["主人一去池水绝，池鹤散飞不相别。","青天漫漫碧海重，知向何山风雪中？","万里虽然音影在，向心终是死生同。","池边巢破松树死，树头年年乌生子。"],"theme":"送别","theme2":[],"style":"豪放","style2":[],"mood":"悲怆","mood2":[],"scene":["鸟"],"cats":{"抒情":["离别"],"动物":["写鸟"]},"theme_conf":0.667},{"uid":"648b7a06-ca8e-44e6-9597-c7d25395b78b","title":"赋得铁马鞭","author":"戎昱","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["成器虽因匠，怀刚本自天。","为怜持寸节，长拟静三边。","未入英髦用，空存铁石坚。","希君剖腹取，还解抱龙泉。"],"theme":"咏物","theme2":[],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":[],"cats":{"抒情":["爱国"],"动物":["写马"]},"theme_conf":1.0},{"uid":"82664df2-6554-44d5-ad5c-fceffb3c45bc","title":"鹤警露","author":"陈季","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["南国商飙动，东臯野鹤鸣。","溪松寒暂宿，露草滴还惊。","欲有高飞意，空闻召侣情。","风间传藻质，月下引清声。","未假抟扶势，焉知羽翼轻。","吾君开太液，愿得应皇明。"],"theme":"山水田园","theme2":[],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"动物":["写鸟"]},"theme_conf":1.0},{"uid":"cp0ddc73d1a3910a","title":"竹马子・竹马儿","author":"柳永","dynasty":"宋","section":"宋词","form":"词","paragraphs":["登孤垒荒凉，危亭旷望，静临烟渚。","对雌霓挂雨，雄风拂槛，微收烦暑。","渐觉一叶惊秋，残蝉噪晚，素商时序。","览景想前欢，指神京，非雾非烟深处。","向此成追感，新愁易积，故人难聚。","凭高尽日凝伫。","赢得消魂无语。","极目霁霭霏微，暝鸦零乱，萧索江城暮。","南楼画角，又送残阳去。"],"theme":"送别","theme2":["山水田园"],"style":"沉郁","style2":[],"mood":"愁怨","mood2":["孤寂","欢愉"],"scene":["雨","楼","江","秋","夏"],"cats":{"抒情":["友情","伤感","孤独"],"四季":["夏天","秋天"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.639},{"uid":"8a9195a1-6b5d-4054-b785-21350c64f373","title":"谢王郎中见赠琴鹤","author":"顾况","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["此琴等焦尾，此鹤方胎生。","赴节何徘徊，理感物自幷。","独立江海上，一弹天地清。","朱弦动瑶华，白羽飘玉京。","因想羡门辈，眇然四体轻。","子乔翔邓林，王母游层城。","忽如启灵署，鸾凤相和鸣。","何由玉女床，去食琅玕英。"],"theme":"咏物","theme2":["闲适隐逸"],"style":"婉约","style2":[],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["孤独","感恩"],"动物":["写鸟"]},"theme_conf":0.76},{"uid":"c9e8cd22-8ed0-407b-a20a-8c4650f1fa2e","title":"燕子来舟中作","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["湖南为客动经春，燕子衔泥两度新。","旧入故园常识主，如今社日远看人。","可怜处处巢君室，何异飘飘托此身。","暂语船樯还起去，穿花落水益沾巾。"],"theme":"羁旅思乡","theme2":["山水田园","节令风俗"],"style":"清新","style2":[],"mood":"孤寂","mood2":[],"scene":["舟","鸟"],"cats":{"抒情":["思乡"],"动物":["写鸟"]},"theme_conf":0.45},{"uid":"df7ccf42-3d7d-4927-a388-43ec90d7ec7b","title":"送鸿举游江[西]","author":"刘禹锡","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["禅客学禅兼学文，出山初似无心云。","从风卷舒来何处，缭绕巴山不得去。","山州古寺好闲居，读尽龙王宫里书。","使君滩头拣石砚，白帝城边寻野蔬。","忽然登高心瞥起，又欲浮杯信流水。","烟波浩淼鱼鸟情，东去三千三百里。","荆门峡断无盘涡，湘平汉阔清光多。","庐山雾开见瀑布，江西月净闻渔歌。","钟陵八郡多名守，半是西方社中友。","与师相见便谈空，想得高斋狮子吼。"],"theme":"送别","theme2":["闲适隐逸","哲理悟道"],"style":"冲淡","style2":[],"mood":"恬淡","mood2":[],"scene":["江","山"],"cats":{"山水":["庐山","江河","瀑布"],"人生":["哲理"],"动物":["写鸟"]},"theme_conf":0.351},{"uid":"80fe70cd-6e63-48eb-9c1e-ab26330d45d9","title":"崔九欲往南山马上口号与别","author":"裴迪","dynasty":"唐","section":"唐诗","form":"五言绝句","paragraphs":["归山深浅去，须尽丘壑美。","莫学武陵人，暂游桃源里。"],"theme":"送别","theme2":[],"style":"婉约","style2":[],"mood":"惆怅","mood2":[],"scene":["山"],"cats":{"抒情":["离别"],"动物":["写马"]},"theme_conf":0.677},{"uid":"a46125e8-7617-40ac-90f6-35d2f9af010c","title":"杂曲歌辞 爱妾换马 二","author":"张祜","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绮阁香销华厩空，忍将行雨换追风。","休怜柳叶双眉翠，却爱桃花两耳红。","侍宴永辞春色里，趁朝休立漏声中。","恩劳未尽情先尽，暗泣嘶风两意同。"],"theme":"闺情宫怨","theme2":[],"style":"绮丽","style2":["婉约"],"mood":"悲怆","mood2":["欢愉"],"scene":["花","春","雨"],"cats":{"抒情":["闺怨"],"四季":["春天"],"动物":["写马"]},"theme_conf":0.729},{"uid":"8c067a87-d475-491d-8786-b811118cfce2","title":"相和歌辞 雁门太守行","author":"庄南杰","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["旌旗闪闪摇天末，长笛横吹虏尘阔。","跨下嘶风白练狞，腰间切玉青蛇活。","击革𪭢金燧牛尾，犬羊兵败如山死。","九泉寂寞葬秋虫，湿云荒草啼秋思。"],"theme":"边塞征战","theme2":["羁旅思乡","悼亡挽歌","山水田园"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","秋"],"cats":{"抒情":["思乡","孤独","悼亡"],"四季":["秋天"],"动物":["写鸟"]},"theme_conf":0.301},{"uid":"2236d4fc-b6ec-481c-97cb-ac7609dd8382","title":"咏司马彪续汉志","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["二仪初创象，三才乃分位。","非惟树司牧，固亦垂文字。","緜代更膺期，芳图无辍记。","炎汉承君道，英谟纂神器。","潜龙既可跃，逵兔奚难致。","前史殚妙词，后昆沈雅思。","书言扬盛迹，补阙兴洪志。","川谷犹旧途，郡国开新意。","梅山未觉朽，谷水谁云异。","车服随名表，文物因时置。","凤戟翼康衢，銮舆总柔辔。","清浊必能澄，洪纤幸无弃。","观仪不失序，遵礼方由事。","政宣竹律和，时平玉条备。","文囿雕奇彩，艺门蕴深致。","云飞星共流，风扬月兼至。","类禋遵令典，坛壝资良地。","五胜竟无违，百司诚有庇。","粤予承暇景，谈丛引泉秘。","讨论穷义府，看核披经笥。","大辨良难仰，小学终先匮。","闻道谅知荣，含毫孰忘媿。"],"theme":"咏物","theme2":["山水田园"],"style":"清新","style2":["绮丽"],"mood":"孤寂","mood2":[],"scene":[],"cats":{"人生":["梦想"],"动物":["写马"]},"theme_conf":0.533},{"uid":"cp47edac7a31dd39","title":"燕山亭","author":"赵佶","dynasty":"宋","section":"宋词","form":"词","paragraphs":["裁翦冰绡，打叠数重，冷淡燕脂匀注。","新样靓妆，艳溢香融，羞杀蕊珠宫女。","易得凋零，更多少、无情风雨。","愁苦。","闲院落凄凉，几番春暮。","凭寄离恨重重，这双燕，何曾会人言语。","天遥地远，万水千山，知他故宫何处。","怎不思量，除梦里、有时会去。","无据。","和梦也、有时不做。"],"theme":"送别","theme2":["闺情宫怨"],"style":"清新","style2":["沉郁"],"mood":"愁怨","mood2":[],"scene":["山","鸟","雨","花"],"cats":{"抒情":["伤感","闺怨"],"动物":["写鸟"]},"theme_conf":0.537},{"uid":"ff7aca6e-232d-464f-91cf-75f019591e69","title":"酬马八效古见赠","author":"高适","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["深崖无绿竹，秀色徒氛氲。","时代种桃李，无人顾此君。","奈何冰雪操，尚与蒿莱群。","愿托灵仙子，一声吹入云。"],"theme":"咏物","theme2":[],"style":"婉约","style2":[],"mood":"孤寂","mood2":["惆怅"],"scene":["冬","雪"],"cats":{"抒情":["孤独"],"天气":["写雪"],"动物":["写马"]},"theme_conf":0.86},{"uid":"2cb04222-21b9-4866-91a1-7426027b5fa6","title":"题壁画马歌","author":"杜甫","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["韦侯别我有所适，知我怜君画无敌。","戏拈秃笔埽骅骝，歘见骐𬴊出东壁。","一匹龁草一匹嘶，坐看千里当霜蹄。","时危安得真致此，与人同生亦同死。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"恬淡","mood2":["悲怆"],"scene":[],"cats":{"动物":["写马"]},"theme_conf":0.777},{"uid":"cp16bdb8f3299f70","title":"瑞鹤仙","author":"陆淞","dynasty":"宋","section":"宋词","form":"词","paragraphs":["脸霞红印枕。","睡觉来、冠儿还是不整。","屏间麝煤冷。","但眉峰压翠，泪珠弹粉。","堂深昼永。","燕交飞、风帘露井。","恨无人，与说相思，近日带围宽尽。","重省。","残灯朱幌，淡月纱窗，那时风景。","阳台路迥。","云雨梦，便无准。","待归来，先指花梢教看，却把心期细问。","问因循、过了青春，怎生意稳。"],"theme":"闺情宫怨","theme2":["爱情相思","游仙梦幻","山水田园"],"style":"绮丽","style2":["婉约","沉郁"],"mood":"相思","mood2":["愁怨"],"scene":["鸟"],"cats":{"抒情":["爱情","思念","伤感","闺怨"],"人生":["青春"],"动物":["写鸟"]},"theme_conf":0.274},{"uid":"be76202d-c128-4278-b070-dcb351ae96ae","title":"白马","author":"杜甫","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["白马东北来，空鞍贯双箭。","可怜马上郎，意气今谁见。","近时主将戳，中夜商于战。","丧乱死多门，呜呼泪如霰。"],"theme":"边塞征战","theme2":["咏物"],"style":"婉约","style2":["沉郁"],"mood":"慷慨","mood2":["悲怆","愁怨"],"scene":["雪","夜"],"cats":{"抒情":["伤感"],"人生":["战争"],"动物":["写马"]},"theme_conf":0.594},{"uid":"56c66dee-7bd0-403b-81a4-6b5d552e776d","title":"相和歌辞 燕歌行","author":"贾至","dynasty":"唐","section":"唐诗","form":"七言古诗","paragraphs":["国之重镇惟幽都，东威九夷制北胡。","五军精卒三十万，百战百胜擒单于。","前临滹沲后沮水，崇山沃野亘千里。","昔时燕王重贤士，黄金筑台从隗始。","倏忽兴王定蓟丘，汉家又以封王侯。","萧条魏晋为横流，鲜卑窃据朝五州。","我唐区夏余十纪，军容武备赫万祀。","彤弓黄钺授元帅，垦耕大漠为内地。","季秋胶折边草腓，治兵羽猎因出师。","千营万队连旌旗，望之如火忽雷驰。","匈奴慑窜穷发北，大荒万里无尘飞。","隋家昔为天下宰，穷兵黩武征辽海。","南风不竞多死声，鼓卧旗折黄云横。","六军将士皆死尽，战马空鞍归故营。","时迁道革天下平，白环入贡沧海清。","自有农夫已高枕，无劳校尉重横行。"],"theme":"边塞征战","theme2":[],"style":"清新","style2":["豪放","雄浑"],"mood":"孤寂","mood2":["悲怆"],"scene":["鸟","夏"],"cats":{"四季":["夏天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.626},{"uid":"cp8aaa92b7ad5aae","title":"夜飞鹊・夜飞鹊慢","author":"周邦彦","dynasty":"宋","section":"宋词","form":"词","paragraphs":["河桥送人处，凉夜何其。","斜月远堕馀辉。","铜盘烛泪已流尽，霏霏凉露沾衣。","相将散离会，探风前津鼓，树杪参旗。","华骢会意，纵扬鞭、亦自行迟。","迢递路回清野，人语渐无闻，空带愁归。","何意重红满地，遗钿不见，斜径都迷。","兔葵燕麦，向残阳、欲与人齐。","但徘徊班草，欷酹酒，极望天西。"],"theme":"送别","theme2":[],"style":"沉郁","style2":["清新"],"mood":"愁怨","mood2":[],"scene":["夜","鸟"],"cats":{"抒情":["伤感"],"生活":["写桥"],"动物":["写鸟"]},"theme_conf":1.0},{"uid":"63aed9a9-4229-4f68-8fe9-e626ae91b5a0","title":"盐州过胡儿饮马泉","author":"李益","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["绿杨著水草如烟，旧是胡儿饮马泉。","几处吹笳明月夜，何人倚劒白云天。","从来冻合关山路，今日分流汉使前。","莫遣行人照容鬓，恐惊憔悴入新年。"],"theme":"边塞征战","theme2":["山水田园"],"style":"婉约","style2":["清新"],"mood":"慷慨","mood2":[],"scene":["月"],"cats":{"天气":["月亮"],"节日":["春节"],"动物":["写马"]},"theme_conf":0.391},{"uid":"995a9440-f8e3-4a9b-843d-27a34ea8b671","title":"陪李七司马皂江上观造竹桥即日成往来之人免冬寒入水聊题短作简李公二首 一","author":"杜甫","dynasty":"唐","section":"唐诗","form":"七言律诗","paragraphs":["伐竹为桥结构同，褰裳不涉往来通。","天寒白鹤归华表，日落青龙见水中。","顾我老非题柱客，知君才是济川功。","合欢却笑千年事，驱石何时到海东。"],"theme":"山水田园","theme2":[],"style":"幽峭","style2":[],"mood":"欢愉","mood2":["孤寂"],"scene":["冬","江"],"cats":{"四季":["冬天"],"天气":["太阳"],"生活":["写桥"],"动物":["写马"],"植物":["竹子"]},"theme_conf":0.52},{"uid":"e94f7b4c-7e68-4d8b-81b3-053539a689d8","title":"画马篇","author":"高适","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君侯枥上骢，貌在丹青中。","马毛连钱蹄铁色，图画光辉骄玉勒。","马行不动势若来，权奇蹴踏无尘埃。","感兹绝代称妙手，遂令谈者不容口。","麒麟独步自可珍，驽骀万匹知何有，终未如他枥上骢。","载华毂，聘飞鸿，荷君剪拂与君用，一日千里如旋风。"],"theme":"题画咏艺","theme2":[],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独"],"动物":["写马"]},"theme_conf":1.0},{"uid":"e74b2d34-c0a4-4049-a02d-b2d9aa00fd80","title":"横吹曲辞 幽州胡马客歌","author":"李白","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["幽州胡马客，绿眼虎皮冠。","笑拂两只箭，万人不可干。","弯弓若转月，白雁落云端。","双双掉鞭行，游猎向楼兰。","出门不顾后，报国死何难。","天骄五单于，狼戾好凶残。","牛马散北海，割鲜若虎餐。","虽居燕支山，不道朔雪寒。","妇女马上笑，颜如赪玉盘。","飜入射鸟兽，花月醉雕鞍。","旄头四光芒，争战若蜂攒。","白刃洒赤血，流沙为之丹。","名将古谁是，疲兵良可叹。","何时天狼灭？父子得闲安。"],"theme":"边塞征战","theme2":[],"style":"豪放","style2":["沉郁","绮丽"],"mood":"恬淡","mood2":["孤寂","慷慨"],"scene":["鸟"],"cats":{"抒情":["爱国"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":0.574},{"uid":"ce013b49-2360-4975-868d-51f326a07115","title":"梁司马画马歌","author":"顾况","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["画精神，画筋骨，一团旋风瞥灭没。","仰秣如上贺兰山，低头欲饮长城窟。","此马昂然独此群，阿爷是龙飞入云。","黄沙枯碛无寸草，一日行过千里道。","展处把笔欲描时，司马一䯄赛倾倒。"],"theme":"题画咏艺","theme2":["边塞征战"],"style":"绮丽","style2":[],"mood":"孤寂","mood2":[],"scene":[],"cats":{"抒情":["孤独","感恩"],"动物":["写马"]},"theme_conf":0.632},{"uid":"f19370d8-5bc7-42c7-a16b-740337f9e5d8","title":"故燕国相公挽歌二首 一","author":"李嘉祐","dynasty":"唐","section":"唐诗","form":"五言律诗","paragraphs":["文若为全德，留侯是重名。","论公长不宰，因病得无生。","大梦依禅定，高坟共化城。","自应怜寂灭，人世但伤情。"],"theme":"悼亡挽歌","theme2":[],"style":"清新","style2":["沉郁"],"mood":"孤寂","mood2":[],"scene":["鸟"],"cats":{"抒情":["悼亡"],"动物":["写鸟"]},"theme_conf":0.99},{"uid":"84b9a130-8145-4902-aac7-5779c17e3fef","title":"饮马长城窟行","author":"太宗皇帝","dynasty":"唐","section":"唐诗","form":"五言古诗","paragraphs":["塞外悲风切，交河冰已结。","瀚海百重波，阴山千里雪。","迥戍危烽火，层峦引高节。","悠悠卷斾旌，饮马出长城。","寒沙连骑迹，朔吹断边声。","胡尘清玉塞，羌笛韵金钲。","绝漠干戈戢，车徒振原隰。","都尉反龙堆，将军旋马邑。","扬麾氛雾静，纪石功名立。","荒裔一戎衣，灵台凯歌入。"],"theme":"边塞征战","theme2":[],"style":"悲慨","style2":["绮丽"],"mood":"恬淡","mood2":["悲怆"],"scene":["冬","塞外"],"cats":{"抒情":["伤感"],"人生":["战争"],"生活":["边塞"],"动物":["写马"]},"theme_conf":1.0},{"uid":"7715e2f7-4e7e-4794-942e-bfbad57f953d","title":"燕歌行","author":"屈同仙","dynasty":"唐","section":"唐诗","form":"杂言古诗","paragraphs":["君不见渔阳八月塞草腓，征人相对并思归。","云和朔气连天黑，蓬杂惊沙散野飞。","是时天地阴埃遍，瀚海龙城皆习战。","两军鼓角暗相闻，四面旌旗看不见。","昭君远嫁已年多，戎狄无厌不复和。","汉兵候月秋防塞，胡骑乘冰夜渡河。","河塞东西万余里，地与京华不相似。","燕支山下少春晖，黄沙碛里无流水。","金戈玉剑十年征，红粉青楼多怨情。","厌向殊乡久离别，秋来愁听捣衣声。"],"theme":"边塞征战","theme2":[],"style":"绮丽","style2":["清新","豪放"],"mood":"愁怨","mood2":["相思"],"scene":["鸟","塞外","秋"],"cats":{"抒情":["离别","思念","伤感","感恩"],"四季":["秋天"],"人生":["战争"],"生活":["边塞"],"动物":["写鸟"]},"theme_conf":0.592}];
